"""Random word counts, with runs of whitespace of varying length between
words and sometimes around the edges."""


WORDS = ["red", "blue", "north", "south", "up", "down", "cat", "dog"]


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 8)
    words = [rng.choice(WORDS) for _ in range(n)]
    gap = lambda: " " * rng.randint(1, 4)
    text = gap() if rng.random() < 0.3 and words else ""
    text += gap().join(words)
    if words and rng.random() < 0.3:
        text += gap()
    return {"name": "%d words, irregular spacing #%d" % (n, index),
            "stdin": text + "\n"}
